include.oit.glsl:
#ifndef MINECRAFT_OIT_GLSL
#define MINECRAFT_OIT_GLSL

#ifdef OIT
    #include <minecraft:oit_common.glsl>

    #if defined(OIT_TRANSMITTANCE) || defined(OIT_ACCUMULATE)
        #include <minecraft:oit_depth_sample.glsl>
    #endif

